        raise NotImplementedError

    @classmethod
    def from_json(cls, data: dict) -> "VersionRecord":
        raise NotImplementedError

    def to_version_response(self, key_id: str) -> dict:
        """Body of GET .../versions/{v} and .../current. No private material."""
        raise NotImplementedError


